import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import type { Database } from '@/lib/supabase/types'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const UpdateTimeOffSchema = z.object({
  status: z.enum(['approved', 'denied', 'cancelled']).optional(),
  notes: z.string().max(500).nullable().optional(),
})

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string; timeOffId: string }> },
) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id: artistId, timeOffId } = await params

  const body = UpdateTimeOffSchema.safeParse(await request.json())
  if (!body.success) {
    return NextResponse.json({ error: body.error.flatten() }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    // Verify record belongs to this artist + studio
    const { data: existing } = await supabase
      .from('artist_time_off')
      .select('id, status, artist_id, studio_id')
      .eq('id', timeOffId)
      .eq('artist_id', artistId)
      .eq('studio_id', authUser.studioId)
      .single()

    if (!existing) return NextResponse.json({ error: 'Time off not found' }, { status: 404 })

    const isAdmin = authUser.role === 'owner' || authUser.role === 'admin'

    // Only admins can approve/deny; anyone (artist) can cancel their own
    if (body.data.status === 'approved' || body.data.status === 'denied') {
      if (!isAdmin) return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
    }

    // Fetch artist to check if this is the artist's own record
    if (body.data.status === 'cancelled' && !isAdmin) {
      const { data: artist } = await supabase
        .from('artists')
        .select('profile_id')
        .eq('id', artistId)
        .eq('studio_id', authUser.studioId)
        .single()
      if (artist?.profile_id !== authUser.user.id) {
        return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
      }
    }

    type TimeOffUpdate = Database['public']['Tables']['artist_time_off']['Update']
    const patch: TimeOffUpdate = {}
    if (body.data.notes !== undefined) patch.notes = body.data.notes
    if (body.data.status !== undefined) {
      patch.status = body.data.status
      if (body.data.status === 'approved') {
        patch.approved_by = authUser.user.id
        patch.approved_at = new Date().toISOString()
      }
    }

    if (Object.keys(patch).length === 0) {
      return NextResponse.json({ error: 'No fields to update' }, { status: 400 })
    }

    const { data, error } = await supabase
      .from('artist_time_off')
      .update(patch)
      .eq('id', timeOffId)
      .eq('studio_id', authUser.studioId)
      .select()
      .single()

    if (error) {
      logger.error({ err: error, timeOffId }, 'time-off PATCH failed')
      return NextResponse.json({ error: 'Failed to update time off' }, { status: 500 })
    }

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'time-off PATCH unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function DELETE(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string; timeOffId: string }> },
) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id: artistId, timeOffId } = await params

  try {
    const supabase = await createClient()

    const { data: existing } = await supabase
      .from('artist_time_off')
      .select('id, artist_id, studio_id')
      .eq('id', timeOffId)
      .eq('artist_id', artistId)
      .eq('studio_id', authUser.studioId)
      .single()

    if (!existing) return NextResponse.json({ error: 'Time off not found' }, { status: 404 })

    const isAdmin = authUser.role === 'owner' || authUser.role === 'admin'
    if (!isAdmin) return NextResponse.json({ error: 'Forbidden' }, { status: 403 })

    const { error } = await supabase
      .from('artist_time_off')
      .delete()
      .eq('id', timeOffId)
      .eq('studio_id', authUser.studioId)

    if (error) {
      logger.error({ err: error, timeOffId }, 'time-off DELETE failed')
      return NextResponse.json({ error: 'Failed to delete time off' }, { status: 500 })
    }

    return NextResponse.json({ success: true })
  } catch (err) {
    logger.error({ err }, 'time-off DELETE unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { type NextRequest } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import type { ScheduleAppointment } from '@/components/shared/ScheduleTimeline'

const querySchema = z.object({
  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'date must be YYYY-MM-DD'),
})

export async function GET(request: NextRequest) {
  // Auth
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return Response.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // Rate limit
  const { success } = await authedRatelimit.limit(auth.user.authId)
  if (!success) {
    return new Response('Too many requests', {
      status: 429,
      headers: { 'Retry-After': '60' },
    })
  }

  // Validate query param
  const { searchParams } = new URL(request.url)
  const parsed = querySchema.safeParse({ date: searchParams.get('date') })
  if (!parsed.success) {
    return Response.json({ error: parsed.error.format() }, { status: 400 })
  }

  // studioId from session — never from client
  const { studioId } = auth

  try {
    // Sprint 1: appointments table added in Sprint 2.
    // Return typed empty array so hook shape is stable.
    const response: ScheduleAppointment[] = []

    logger.info({ studioId, date: parsed.data.date }, 'dashboard.schedule.fetched')
    return Response.json(response)
  } catch (err) {
    logger.error({ err, studioId }, 'dashboard.schedule.error')
    return Response.json({ error: 'Failed to fetch schedule' }, { status: 500 })
  }
}
